export interface Sealed {
  /** The 256-bit key, in hex: new for every call. */
  key: string;
  nonce: string;
  /** The ciphertext followed by the 16-byte tag, in hex. */
  ciphertext: string;
  /** The ciphertext decrypted again with the same key. */
  opened: string;
}

const HEX = "0123456789abcdef";

function hex(bytes: ArrayBuffer | Uint8Array): string {
  let out = "";
  for (const b of new Uint8Array(bytes)) out += HEX[b >> 4]! + HEX[b & 15]!;
  return out;
}

const utf8 = (text: string) => new TextEncoder().encode(text);

/** SHA-256 of the text's UTF-8 bytes, in hex. */
export async function sha256Async(text: string): Promise<string> {
  return hex(await crypto.subtle.digest("SHA-256", utf8(text)));
}

/** HMAC-SHA256 of the text under the key (both UTF-8), in hex. */
export async function hmacSha256Async(key: string, text: string): Promise<string> {
  const mac = await crypto.subtle.importKey(
    "raw",
    utf8(key),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  return hex(await crypto.subtle.sign("HMAC", mac, utf8(text)));
}

/** AES-256-GCM: seals the text under a new key, then opens it again. */
export async function sealAsync(text: string): Promise<Sealed> {
  const key = await crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, true, [
    "encrypt",
    "decrypt",
  ]);
  const nonce = crypto.getRandomValues(new Uint8Array(12));
  const sealed = await crypto.subtle.encrypt({ name: "AES-GCM", iv: nonce }, key, utf8(text));
  const opened = await crypto.subtle.decrypt({ name: "AES-GCM", iv: nonce }, key, sealed);

  return {
    key: hex(await crypto.subtle.exportKey("raw", key)),
    nonce: hex(nonce),
    ciphertext: hex(sealed),
    opened: new TextDecoder().decode(opened),
  };
}
